
.card {
  width: 100%;
  max-width: 720px;
  background-color: var(--c-deep);
  border: 1px solid var(--c-border);
  box-shadow:
    0 0 24px rgba(0, 240, 255, 0.08),
    inset 0 1px 0 rgba(0, 240, 255, 0.05);
  display: flex;
  flex-direction: column;
  font-family: var(--font-cyber);
  color: var(--c-ghost);
  font-size: 13px;
  line-height: 1.4;
  margin: 0 auto;
  border-radius: 2px;
  overflow: hidden;
}

.content-area {
  padding: 12px;
  min-height: 0;
}

.tab-pane {
  display: none;
  animation: fadeIn 0.35s ease;
}

.tab-pane.active {
  display: block;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
