
.inventory-grid {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.item-row {
  display: flex;
  align-items: center;
  background: var(--c-slate);
  border: 1px solid var(--c-border);
  padding: 8px;
  transition: all 0.2s;
}

.item-row:hover {
  border-color: var(--c-neon);
  box-shadow: 0 0 8px rgba(0, 240, 255, 0.1);
}

.item-icon {
  width: 28px;
  height: 28px;
  background: rgba(0, 240, 255, 0.08);
  border: 1px solid var(--c-border);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-right: 10px;
  font-size: 0.85rem;
  color: var(--c-neon);
}

.item-detail {
  flex: 1;
}

.item-name {
  font-weight: 700;
  display: block;
  font-size: 0.88rem;
  color: var(--c-ghost);
}

.item-desc {
  font-size: 0.72rem;
  color: var(--c-faint);
}

.item-count {
  background: var(--c-border);
  color: var(--c-ghost);
  padding: 2px 6px;
  font-size: 0.72rem;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.empty-state {
  text-align: center;
  color: var(--c-faint);
  padding: 16px;
  font-style: italic;
  font-size: 0.85rem;
}
