
.player-layout {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.stat-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.stat-card {
  background: var(--c-slate);
  border: 1px solid var(--c-border);
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.stat-label {
  font-size: 0.65rem;
  color: var(--c-faint);
  letter-spacing: 1px;
  font-weight: 600;
  text-transform: uppercase;
}

.stat-value {
  font-size: 0.95rem;
  font-weight: 700;
  color: var(--c-ghost);
}

.stat-value.system {
  color: var(--c-neon);
  text-shadow: 0 0 6px rgba(0, 240, 255, 0.3);
}

.stat-value.level {
  color: var(--c-amber);
  text-shadow: 0 0 6px rgba(245, 158, 11, 0.3);
}

.stat-value.good {
  color: #34d399;
}

.stat-value.minor {
  color: var(--c-amber);
}

.stat-value.warn {
  color: #f97316;
}

.stat-value.danger {
  color: var(--c-warn);
  animation: pulse 1.5s infinite;
}

@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

@media (max-width: 400px) {
  .stat-row {
    grid-template-columns: 1fr;
  }
}
